package main

import (
	"fmt"
	"os"
	"path/filepath"
)

func main() {
	progName := filepath.Base(os.Args[0])
	// Combine HWATCH env var args with argv
	args := buildArgs(os.Args[1:])
	cfg, err := parseArgs(progName, args)
	if err != nil {
		if err == errHelp {
			printHelp(progName)
			os.Exit(0)
		}
		if err == errVersion {
			fmt.Println("hwatch 0.3.19")
			os.Exit(0)
		}
		fmt.Fprintf(os.Stderr, "error: %s\n\nFor more information, try '--help'.\n", err.Error())
		os.Exit(2)
	}
	// Validate command or logfile
	if len(cfg.Command) == 0 && cfg.Logfile == "" {
		fmt.Fprintf(os.Stderr, "error: command not specified and logfile is empty.\n\nUsage: %s [OPTIONS] [command]...\n\nFor more information, try '--help'.\n", progName)
		os.Exit(2)
	}
	// If command empty but logfile set, we just read-print logfile? Or nothing in batch mode.
	// For batch mode:
	if cfg.Batch {
		runBatch(cfg)
		return
	}
	// TUI mode: if no TTY, silently exit
	runTUI(cfg)
}
