cat > main.go << 'GOEOF'
package main

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"os/signal"
	"path/filepath"
	"strconv"
	"strings"
	"syscall"
	"time"
)

const versionStr = "hwatch 0.3.19"

// -------------------- Config --------------------

type config struct {
	Batch             bool
	Beep              bool
	Border            bool
	WithScrollbar     bool
	Mouse             bool
	Color             bool
	Reverse           bool
	Compress          bool
	NoTitle           bool
	EnableSummaryChar bool
	LineNumber        bool
	NoHelpBanner      bool
	NoSummary         bool
	Exec              bool
	DiffOutputOnly    bool
	Precise           bool

	AfterCommand string

	LogfileSet bool
	Logfile    string

	Shell    string
	Interval float64
	Limit    int64
	TabSize  int64

	DifferencesSet bool
	Differences    string // none, watch, line, word

	OutputMode string // output, stdout, stderr

	Keymaps []string

	Command []string
}

func defaultConfig() *config {
	return &config{
		Shell:       "sh -c",
		Interval:    2.0,
		Limit:       5000,
		TabSize:     4,
		Differences: "none",
		OutputMode:  "output",
	}
}

// -------------------- CLI parsing --------------------

var (
	errHelp    = errors.New("__help__")
	errVersion = errors.New("__version__")
)

// Errors formatted like clap
type clapErr struct{ msg string }

func (e *clapErr) Error() string { return e.msg }

func parseArgs(progName string, rawArgs []string) (*config, error) {
	cfg := defaultConfig()

	// Track whether -d/--differences provided without value (treated as 'watch')
	// Track whether -o/--output provided without value (treated as 'output')

	// Split into tokens handling --opt=value
	// We'll allow grouping of short bool flags (e.g. -bc)
	args := expandEquals(rawArgs)

	var pendingCommand []string
	trailing := false
	i := 0
	for i < len(args) {
		a := args[i]
		if trailing {
			pendingCommand = append(pendingCommand, a)
			i++
			continue
		}
		if a == "--" {
			trailing = true
			i++
			continue
		}
		if len(a) >= 2 && a[0] == '-' && a[1] != '-' {
			// short option(s)
			// Could be -b, -bc, -n2, -n 2, -bnfoo, etc.
			// Walk chars
			j := 1
			for j < len(a) {
				c := a[j]
				consumed, value, hasValue, remainder, err := consumeShortFlag(c, cfg, a, j, args, i)
				if err != nil {
					return nil, err
				}
				if consumed == shortHelp {
					return nil, errHelp
				}
				if consumed == shortVersion {
					return nil, errVersion
				}
				if hasValue {
					// When short flag takes a value, apply the value
					if err := applyShortOption(c, value, cfg); err != nil {
						return nil, err
					}
				} else {
					// Bool flag
					applyShortBool(c, cfg)
				}
				// how j/i advance
				if remainder.consumedArg {
					i++
				}
				if remainder.consumedValueInline {
					j = len(a) // done
				} else {
					j++
				}
				_ = consumed
			}
			i++
			continue
		}
		if len(a) >= 2 && a[0] == '-' && a[1] == '-' {
			name := a[2:]
			// Check long flag
			err := applyLongFlag(name, args, &i, cfg)
			if err != nil {
				if err == errTrailing {
					trailing = true
					i++
					pendingCommand = append(pendingCommand, a)
					continue
				}
				return nil, err
			}
			i++
			continue
		}
		// positional - start of command; after first positional, allow trailing with hyphens
		pendingCommand = append(pendingCommand, a)
		trailing = true
		i++
	}

	cfg.Command = pendingCommand
	return cfg, nil
}

// expandEquals splits "--foo=bar" into ["--foo", "bar"]
func expandEquals(args []string) []string {
	var out []string
	for _, a := range args {
		if strings.HasPrefix(a, "--") && strings.Contains(a, "=") {
			idx := strings.Index(a, "=")
			out = append(out, a[:idx], a[idx+1:])
			continue
		}
		out = append(out, a)
	}
	return out
}

// Short flag meta constants
const (
	shortNormal = iota
	shortHelp
	shortVersion
)

type shortRemainder struct {
	consumedArg         bool // consumed the next args[i+1]
	consumedValueInline bool // consumed rest of current arg as value
}

// consumeShortFlag examines a short flag character
// Returns type, (for options) value, hasValue, remainder info, error.
// We partially parse here but apply in applyShortBool/applyShortOption.
func consumeShortFlag(c byte, cfg *config, a string, j int, args []string, i int) (int, string, bool, shortRemainder, error) {
	switch c {
	case 'h':
		return shortHelp, "", false, shortRemainder{}, nil
	case 'V':
		return shortVersion, "", false, shortRemainder{}, nil
	case 'b', 'B', 'c', 'r', 'C', 't', 'N', 'x', 'O':
		// bool flag
		return shortNormal, "", false, shortRemainder{}, nil
	case 'A', 's', 'n', 'L', 'K':
		// option requiring a value
		// Value comes from: rest of current arg if any, else next arg
		var value string
		var rem shortRemainder
		if j+1 < len(a) {
			value = a[j+1:]
			rem.consumedValueInline = true
		} else {
			if i+1 >= len(args) {
				longName := shortToLong(c)
				return shortNormal, "", false, shortRemainder{}, &clapErr{
					msg: fmt.Sprintf("a value is required for '%s' but none was supplied", longName),
				}
			}
			value = args[i+1]
			rem.consumedArg = true
		}
		return shortNormal, value, true, rem, nil
	case 'l':
		// optional value
		var value string
		var hasValue bool
		var rem shortRemainder
		if j+1 < len(a) {
			value = a[j+1:]
			hasValue = true
			rem.consumedValueInline = true
		} else if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
			value = args[i+1]
			hasValue = true
			rem.consumedArg = true
		}
		return shortNormal, value, hasValue, rem, nil
	case 'd':
		// optional value with possible values
		var value string
		var hasValue bool
		var rem shortRemainder
		if j+1 < len(a) {
			value = a[j+1:]
			hasValue = true
			rem.consumedValueInline = true
		} else if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
			// Only consume as value if it's a valid choice
			next := args[i+1]
			if next == "none" || next == "watch" || next == "line" || next == "word" {
				value = next
				hasValue = true
				rem.consumedArg = true
			}
		}
		return shortNormal, value, hasValue, rem, nil
	case 'o':
		// optional value with possible values
		var value string
		var hasValue bool
		var rem shortRemainder
		if j+1 < len(a) {
			value = a[j+1:]
			hasValue = true
			rem.consumedValueInline = true
		} else if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
			next := args[i+1]
			if next == "output" || next == "stdout" || next == "stderr" {
				value = next
				hasValue = true
				rem.consumedArg = true
			}
		}
		return shortNormal, value, hasValue, rem, nil
	default:
		return shortNormal, "", false, shortRemainder{}, &clapErr{msg: fmt.Sprintf("unexpected argument '-%c' found", c)}
	}
}

func shortToLong(c byte) string {
	switch c {
	case 'A':
		return "--aftercommand <after_command>"
	case 's':
		return "--shell <shell_command>"
	case 'n':
		return "--interval <interval>"
	case 'L':
		return "--limit <limit>"
	case 'K':
		return "--keymap <keymap>"
	}
	return fmt.Sprintf("-%c", c)
}

func applyShortBool(c byte, cfg *config) {
	switch c {
	case 'b':
		cfg.Batch = true
	case 'B':
		cfg.Beep = true
	case 'c':
		cfg.Color = true
	case 'r':
		cfg.Reverse = true
	case 'C':
		cfg.Compress = true
	case 't':
		cfg.NoTitle = true
	case 'N':
		cfg.LineNumber = true
	case 'x':
		cfg.Exec = true
	case 'O':
		cfg.DiffOutputOnly = true
	}
}

func applyShortOption(c byte, value string, cfg *config) error {
	switch c {
	case 'A':
		cfg.AfterCommand = value
	case 'l':
		cfg.LogfileSet = true
		cfg.Logfile = value
	case 's':
		cfg.Shell = value
	case 'n':
		f, err := strconv.ParseFloat(strings.Replace(value, ",", ".", 1), 64)
		if err != nil {
			return &clapErr{msg: fmt.Sprintf("invalid value '%s' for '--interval <interval>': invalid float literal", value)}
		}
		cfg.Interval = f
	case 'L':
		n, err := strconv.ParseInt(value, 10, 64)
		if err != nil {
			return &clapErr{msg: fmt.Sprintf("invalid value '%s' for '--limit <limit>': invalid digit found in string", value)}
		}
		cfg.Limit = n
	case 'd':
		if !isValidDiff(value) {
			return &clapErr{msg: fmt.Sprintf("invalid value '%s' for '--differences [<differences>]'\n  [possible values: none, watch, line, word]", value)}
		}
		cfg.DifferencesSet = true
		cfg.Differences = value
	case 'o':
		if !isValidOutput(value) {
			return &clapErr{msg: fmt.Sprintf("invalid value '%s' for '--output [<output>]'\n  [possible values: output, stdout, stderr]", value)}
		}
		cfg.OutputMode = value
	case 'K':
		cfg.Keymaps = append(cfg.Keymaps, value)
	}
	return nil
}

var errTrailing = errors.New("__trailing__")

func applyLongFlag(name string, args []string, i *int, cfg *config) error {
	// Split name from possibly embedded value already handled via expandEquals
	key := name
	valueAvailable := false
	var valueFromArgs string
	getValue := func(errName string) (string, error) {
		if valueAvailable {
			return valueFromArgs, nil
		}
		if *i+1 >= len(args) {
			return "", &clapErr{msg: fmt.Sprintf("a value is required for '%s' but none was supplied", errName)}
		}
		*i++
		return args[*i], nil
	}
	_ = getValue

	switch key {
	case "help":
		return errHelp
	case "version":
		return errVersion
	case "batch":
		cfg.Batch = true
	case "beep":
		cfg.Beep = true
	case "border":
		cfg.Border = true
	case "with-scrollbar":
		cfg.WithScrollbar = true
	case "mouse":
		cfg.Mouse = true
	case "color":
		cfg.Color = true
	case "reverse":
		cfg.Reverse = true
	case "compress":
		cfg.Compress = true
	case "no-title":
		cfg.NoTitle = true
	case "enable-summary-char":
		cfg.EnableSummaryChar = true
	case "line-number":
		cfg.LineNumber = true
	case "no-help-banner":
		cfg.NoHelpBanner = true
	case "no-summary":
		cfg.NoSummary = true
	case "exec":
		cfg.Exec = true
	case "diff-output-only":
		cfg.DiffOutputOnly = true
	case "precise":
		cfg.Precise = true
	case "aftercommand":
		v, err := getValue("--aftercommand <after_command>")
		if err != nil {
			return err
		}
		cfg.AfterCommand = v
	case "logfile":
		// Optional value
		cfg.LogfileSet = true
		if *i+1 < len(args) && !strings.HasPrefix(args[*i+1], "-") {
			*i++
			cfg.Logfile = args[*i]
		}
	case "shell":
		v, err := getValue("--shell <shell_command>")
		if err != nil {
			return err
		}
		cfg.Shell = v
	case "interval":
		v, err := getValue("--interval <interval>")
		if err != nil {
			return err
		}
		f, perr := strconv.ParseFloat(strings.Replace(v, ",", ".", 1), 64)
		if perr != nil {
			return &clapErr{msg: fmt.Sprintf("invalid value '%s' for '--interval <interval>': invalid float literal", v)}
		}
		cfg.Interval = f
	case "limit":
		v, err := getValue("--limit <limit>")
		if err != nil {
			return err
		}
		n, perr := strconv.ParseInt(v, 10, 64)
		if perr != nil {
			return &clapErr{msg: fmt.Sprintf("invalid value '%s' for '--limit <limit>': invalid digit found in string", v)}
		}
		cfg.Limit = n
	case "tab-size":
		v, err := getValue("--tab-size <tab_size>")
		if err != nil {
			return err
		}
		n, perr := strconv.ParseInt(v, 10, 64)
		if perr != nil {
			return &clapErr{msg: fmt.Sprintf("invalid value '%s' for '--tab-size <tab_size>': invalid digit found in string", v)}
		}
		cfg.TabSize = n
	case "differences":
		// Optional value
		cfg.DifferencesSet = true
		cfg.Differences = "watch" // default when flag only
		if *i+1 < len(args) && !strings.HasPrefix(args[*i+1], "-") {
			next := args[*i+1]
			if isValidDiff(next) {
				*i++
				cfg.Differences = next
			} else {
				// if not valid choice and is likely a positional/cmd, don't consume
				// But clap would error out if the user tries --differences=foo or --differences foo
				// We can't tell here whether the user meant it as value
				return &clapErr{msg: fmt.Sprintf("invalid value '%s' for '--differences [<differences>]'\n  [possible values: none, watch, line, word]", next)}
			}
		}
	case "output":
		// Optional value
		if *i+1 < len(args) && !strings.HasPrefix(args[*i+1], "-") {
			next := args[*i+1]
			if isValidOutput(next) {
				*i++
				cfg.OutputMode = next
			} else {
				return &clapErr{msg: fmt.Sprintf("invalid value '%s' for '--output [<output>]'\n  [possible values: output, stdout, stderr]", next)}
			}
		}
	case "keymap":
		v, err := getValue("--keymap <keymap>")
		if err != nil {
			return err
		}
		cfg.Keymaps = append(cfg.Keymaps, v)
	default:
		// Unknown long option - treat as part of command (trailing)
		return errTrailing
	}
	return nil
}

func isValidDiff(s string) bool {
	switch s {
	case "none", "watch", "line", "word":
		return true
	}
	return false
}

func isValidOutput(s string) bool {
	switch s {
	case "output", "stdout", "stderr":
		return true
	}
	return false
}

// -------------------- Help / Usage --------------------

func printHelp(progName string) {
	fmt.Println(`A modern alternative to the watch command, records the differences in execution results and can check this differences at after.`)
	fmt.Println()
	fmt.Printf("Usage: %s [OPTIONS] [command]...\n", progName)
	fmt.Println()
	fmt.Println(`Arguments:
  [command]...  

Options:
  -b, --batch                         output execution results to stdout
  -B, --beep                          beep if command has a change result
      --border                        Surround each pane with a border frame
      --with-scrollbar                When the border option is enabled, display scrollbar on the right side of watch pane.
      --mouse                         enable mouse wheel support. With this option, copying text with your terminal may be harder. Try holding the Shift key.
  -c, --color                         interpret ANSI color and style sequences
  -r, --reverse                       display text upside down.
  -C, --compress                      Compress data in memory. Note: If the output of the command is small, you may not get the desired effect.
  -t, --no-title                      hide the UI on start. Use ` + "`t`" + ` to toggle it.
      --enable-summary-char           collect character-level diff count in summary.
  -N, --line-number                   show line number
      --no-help-banner                hide the "Display help with h key" message
      --no-summary                    disable the calculation for summary that is running behind the scenes, and disable the summary function in the first place.
  -x, --exec                          Run the command directly, not through the shell. Much like the ` + "`-x`" + ` option of the watch command.
  -O, --diff-output-only              Display only the lines with differences during ` + "`line`" + ` diff and ` + "`word`" + ` diff.
  -A, --aftercommand <after_command>  Executes the specified command if the output changes. Information about changes is stored in json format in environment variable ${HWATCH_DATA}.
  -l, --logfile [<logfile>]           logging file. if a log file is already used, its contents will be read and executed.
  -s, --shell <shell_command>         shell to use at runtime. can also insert the command to the location specified by {COMMAND}. [default: "sh -c"]
  -n, --interval <interval>           seconds to wait between updates [default: 2]
      --precise                       Attempt to run as close to the interval as possible, regardless of how long the command takes to run
  -L, --limit <limit>                 Set the number of history records to keep. only work in watch mode. Set ` + "`0`" + ` for unlimited recording. (default: 5000) [default: 5000]
      --tab-size <tab_size>           Specifying tab display size [default: 4]
  -d, --differences [<differences>]   highlight changes between updates [possible values: none, watch, line, word]
  -o, --output [<output>]             Select command output. [default: output] [possible values: output, stdout, stderr]
  -K, --keymap <keymap>               Add keymap
  -h, --help                          Print help
  -V, --version                       Print version`)
}

// Print short usage for errors
func printUsageError(msg, progName string) {
	fmt.Fprintf(os.Stderr, "error: %s\n\nUsage: %s [OPTIONS] [command]...\n\nFor more information, try '--help'.\n", msg, progName)
}

// -------------------- Main --------------------

func main() {
	progName := filepath.Base(os.Args[0])
	rawArgs := buildArgs(os.Args[1:])
	cfg, err := parseArgs(progName, rawArgs)
	if err != nil {
		if err == errHelp {
			printHelp(progName)
			return
		}
		if err == errVersion {
			fmt.Println(versionStr)
			return
		}
		fmt.Fprintf(os.Stderr, "error: %s\n\nFor more information, try '--help'.\n", err.Error())
		os.Exit(2)
	}

	if len(cfg.Command) == 0 && !cfg.LogfileSet {
		printUsageError("command not specified and logfile is empty.", progName)
		os.Exit(2)
	}

	if cfg.Batch {
		runBatch(cfg)
		return
	}

	// TUI mode: minimal implementation. If stdout is not a TTY, exit silently.
	runTUI(cfg)
}

// buildArgs prepends HWATCH env var args to current argv
func buildArgs(argv []string) []string {
	envArgs := os.Getenv("HWATCH")
	if envArgs == "" {
		return argv
	}
	tokens := splitShell(envArgs)
	return append(tokens, argv...)
}

// splitShell splits a string into shell-like tokens. Simple whitespace split.
func splitShell(s string) []string {
	var out []string
	var cur strings.Builder
	in := false
	quote := byte(0)
	for i := 0; i < len(s); i++ {
		c := s[i]
		if quote != 0 {
			if c == quote {
				quote = 0
				continue
			}
			cur.WriteByte(c)
			continue
		}
		if c == '"' || c == '\'' {
			quote = c
			in = true
			continue
		}
		if c == ' ' || c == '\t' {
			if in {
				out = append(out, cur.String())
				cur.Reset()
				in = false
			}
			continue
		}
		cur.WriteByte(c)
		in = true
	}
	if in {
		out = append(out, cur.String())
	}
	return out
}

// -------------------- Batch mode --------------------

// commandResult holds one execution's info
type commandResult struct {
	Timestamp string
	Command   string
	Status    bool
	Output    string
	Stdout    string
	Stderr    string
}

func (r commandResult) json() string {
	var b strings.Builder
	b.WriteString("{")
	b.WriteString(`"timestamp":`)
	b.WriteString(jsonString(r.Timestamp))
	b.WriteString(`,"command":`)
	b.WriteString(jsonString(r.Command))
	b.WriteString(`,"status":`)
	if r.Status {
		b.WriteString("true")
	} else {
		b.WriteString("false")
	}
	b.WriteString(`,"output":`)
	b.WriteString(jsonString(r.Output))
	b.WriteString(`,"stdout":`)
	b.WriteString(jsonString(r.Stdout))
	b.WriteString(`,"stderr":`)
	b.WriteString(jsonString(r.Stderr))
	b.WriteString("}")
	return b.String()
}

func jsonString(s string) string {
	// Minimal JSON string encoder
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		case '\b':
			b.WriteString(`\b`)
		case '\f':
			b.WriteString(`\f`)
		default:
			if r < 0x20 {
				b.WriteString(fmt.Sprintf(`\u%04x`, r))
			} else {
				b.WriteRune(r)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

func runBatch(cfg *config) {
	// Setup signal handler for clean exit
	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, os.Interrupt, syscall.SIGTERM)

	var logFile *os.File
	if cfg.LogfileSet && cfg.Logfile != "" {
		f, err := os.OpenFile(cfg.Logfile, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
		if err != nil {
			fmt.Fprintf(os.Stderr, "cannot open logfile: %v\n", err)
			os.Exit(1)
		}
		logFile = f
		defer logFile.Close()
	}

	// Pending (empty to begin with)
	var pending commandResult
	var prevOutput string
	first := true
	cmdStr := strings.Join(cfg.Command, " ")

	// Write initial empty entry to log
	if logFile != nil {
		fmt.Fprintln(logFile, pending.json())
	}

	done := false
	for !done {
		startTime := time.Now()

		var result commandResult
		if len(cfg.Command) > 0 {
			result = executeCommand(cfg, cmdStr)
		}

		// Batch output: print on first or on change
		if first || result.Output != prevOutput {
			printBatchHeader(result.Timestamp)
			fmt.Print(result.Output)
			if !strings.HasSuffix(result.Output, "\n") {
				fmt.Println()
			} else {
				fmt.Println()
			}
		}

		// Log: write pending (previous)
		if logFile != nil && !first {
			if result.Output != prevOutput {
				fmt.Fprintln(logFile, pending.json())
			}
		}
		pending = result
		prevOutput = result.Output
		first = false

		// Sleep interval, handle signals
		interval := cfg.Interval
		if interval < 0.001 {
			interval = 0.001
		}
		select {
		case <-sigCh:
			done = true
		case <-time.After(time.Until(startTime.Add(time.Duration(interval * float64(time.Second))))):
		}
	}
}

func printBatchHeader(ts string) {
	// 5 '=', [ts] (25 chars: "[YYYY-MM-DD HH:MM:SS.sss]"), 25 '='
	left := "====="
	right := "========================="
	fmt.Printf("\x1b[38;5;240m%s[%s]%s\x1b[0m\n", left, ts, right)
}

// executeCommand runs the configured command and captures output.
func executeCommand(cfg *config, cmdStr string) commandResult {
	ts := time.Now().Format("2006-01-02 15:04:05.000")

	var cmd *exec.Cmd
	if cfg.Exec {
		// Run directly
		if len(cfg.Command) == 0 {
			return commandResult{Timestamp: ts, Command: cmdStr, Status: true}
		}
		cmd = exec.Command(cfg.Command[0], cfg.Command[1:]...)
	} else {
		// Shell
		shellParts := strings.Fields(cfg.Shell)
		if len(shellParts) == 0 {
			shellParts = []string{"sh", "-c"}
		}
		// Substitute {COMMAND}
		hasPlaceholder := false
		newParts := make([]string, 0, len(shellParts)+1)
		for _, p := range shellParts {
			if strings.Contains(p, "{COMMAND}") {
				p = strings.ReplaceAll(p, "{COMMAND}", cmdStr)
				hasPlaceholder = true
			}
			newParts = append(newParts, p)
		}
		if !hasPlaceholder {
			newParts = append(newParts, cmdStr)
		}
		cmd = exec.Command(newParts[0], newParts[1:]...)
	}

	var stdout, stderr, combined bytes.Buffer
	// Use multiwriter for combined output (interleave)
	cmd.Stdout = io.MultiWriter(&stdout, &combined)
	cmd.Stderr = io.MultiWriter(&stderr, &combined)
	err := cmd.Run()
	status := err == nil

	// Determine output based on mode
	var output string
	switch cfg.OutputMode {
	case "stdout":
		output = stdout.String()
	case "stderr":
		output = stderr.String()
	default:
		output = combined.String()
	}

	return commandResult{
		Timestamp: ts,
		Command:   cmdStr,
		Status:    status,
		Output:    output,
		Stdout:    stdout.String(),
		Stderr:    stderr.String(),
	}
}

// -------------------- TUI (minimal) --------------------

func runTUI(cfg *config) {
	// Check if stdout is a TTY
	fi, err := os.Stdout.Stat()
	if err != nil || (fi.Mode()&os.ModeCharDevice) == 0 {
		// Not a TTY - exit silently
		return
	}
	// Minimal TUI: not implemented. Exit silently.
	// In a proper implementation, this would be a full TUI.
	return
}
