var validKeymapActions = map[string]bool{
	"up":                       true,
	"down":                     true,
	"page_up":                  true,
	"page_down":                true,
	"move_top":                 true,
	"move_end":                 true,
	"scroll_left":              true,
	"scroll_right":             true,
	"scroll_horizontal_end":    true,
	"scroll_horizontal_home":   true,
	"toggle_forcus":            true,
	"toggle_color":             true,
	"toggle_line_number":       true,
	"toggle_reverse":           true,
	"toggle_diff_mode":         true,
	"toggle_mouse_support":     true,
	"toggle_output_mode":       true,
	"toggle_border":            true,
	"interval_plus":            true,
	"interval_minus":           true,
	"change_filter_mode":       true,
	"quit":                     true,
	"help":                     true,
	"cancel":                   true,
}

func isValidKeymap(s string) bool {
	// Format: key=action or modifier-key=action
	idx := -1
	// find last '='? Actually format is key=action, single '='
	idx = indexByte(s, '=')
	if idx <= 0 || idx == len(s)-1 {
		return false
	}
	action := s[idx+1:]
	_, ok := validKeymapActions[action]
	return ok
}

func indexByte(s string, c byte) int {
	for i := 0; i < len(s); i++ {
		if s[i] == c {
			return i
		}
	}
	return -1
}
