// loadLastCommand reads the last JSON line from the log file and extracts the "command" field.
func loadLastCommand(path string) string {
	data, err := os.ReadFile(path)
	if err != nil {
		return ""
	}
	lines := strings.Split(string(data), "\n")
	for i := len(lines) - 1; i >= 0; i-- {
		line := strings.TrimSpace(lines[i])
		if line == "" {
			continue
		}
		// naive parse: look for "command":"..."
		needle := `"command":"`
		idx := strings.Index(line, needle)
		if idx < 0 {
			continue
		}
		start := idx + len(needle)
		// find closing quote
		for end := start; end < len(line); end++ {
			if line[end] == '\\' {
				end++
				continue
			}
			if line[end] == '"' {
				raw := line[start:end]
				if raw == "" {
					break // skip empty placeholder
				}
				// unescape
				return unescapeJSONStr(raw)
			}
		}
	}
	return ""
}

func unescapeJSONStr(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\\' && i+1 < len(s) {
			nxt := s[i+1]
			switch nxt {
			case 'n':
				b.WriteByte('\n')
			case 't':
				b.WriteByte('\t')
			case 'r':
				b.WriteByte('\r')
			case '"':
				b.WriteByte('"')
			case '\\':
				b.WriteByte('\\')
			default:
				b.WriteByte(nxt)
			}
			i++
			continue
		}
		b.WriteByte(c)
	}
	return b.String()
}
